import{_ as s}from"./chunks/flaky-detection.CN9mtzEz.js";import{_ as r,C as i,o,c as n,j as t,a as l,E as d,ak as h}from"./chunks/framework.sV-XtlWr.js";const k=JSON.parse('{"title":"Flaky tests","description":"","frontmatter":{"title":"Flaky tests","lang":"en-US"},"headers":[],"relativePath":"features/flaky-tests.md","filePath":"features/flaky-tests.md","lastUpdated":1788720938000}'),c={name:"features/flaky-tests.md"};function u(p,e,g,f,m,y){const a=i("Needs");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"flaky-tests",tabindex:"-1"},[l("Flaky tests "),t("a",{class:"header-anchor",href:"#flaky-tests","aria-label":'Permalink to "Flaky tests"'},"​")],-1)),d(a,{reporter:""}),e[1]||(e[1]=h('<p>A single run tells you what failed. A few dozen runs tell you what&#39;s <em>unreliable</em> — and that&#39;s a different, more expensive problem. This page covers what Piwi computes for one project once it has some history: flaky scoring, regression signals, and spec health.</p><p>For the same signals aggregated across every project, see <a href="./analytics.html">Analytics</a>.</p><h2 id="flaky-test-detection" tabindex="-1">Flaky test detection <a class="header-anchor" href="#flaky-test-detection" aria-label="Permalink to &quot;Flaky test detection&quot;">​</a></h2><p>A test is flaky when its result isn&#39;t deterministic. Piwi computes a <strong>composite flakiness score</strong> per test from three signals:</p><ul><li><strong>Retry passes</strong> — failed on the first attempt, passed on retry.</li><li><strong>Status alternation</strong> — flips between pass and fail across runs.</li><li><strong>Failure rate</strong> — overall proportion of failures.</li></ul><p>The project&#39;s <strong>Failures</strong> tab has a <strong>Flaky</strong> view with a <strong>configurable lookback window</strong> so you can focus on recent behavior or a longer baseline. Each flaky test links to its history and carries a <strong>Quarantine</strong> action.</p><p><strong>Per-environment scoping</strong> — select a single environment in the project&#39;s filter bar and the flaky analysis is scoped to runs from that environment, so you can compare stability across <code>staging</code>, <code>production</code>, and <code>development</code> instead of blending them. (Set the environment via the reporter&#39;s <code>environment</code> option / <code>PIWI_ENVIRONMENT</code>; see the <a href="/guide/reporter.html">reporter</a> docs.)</p><figure><img src="'+s+'" alt="Flaky tests tab listing tests with composite score, failure rate, retry passes, and flip counts"><figcaption>The Flaky view of a project&#39;s Failures tab — each intermittent test scored by retry passes, status flips, and failure rate, ranked by impact and filterable by root-cause category.</figcaption></figure><h3 id="root-cause-classification" tabindex="-1">Root-cause classification <a class="header-anchor" href="#root-cause-classification" aria-label="Permalink to &quot;Root-cause classification&quot;">​</a></h3><p>Every flaky test is automatically tagged with one of five categories, using keyword and distribution heuristics over its errors, steps, and browser spread, sharpened by the failed requests actually captured and by the attempt diff:</p><table tabindex="0"><thead><tr><th>Category</th><th>Typical signals</th></tr></thead><tbody><tr><td><code>timing</code></td><td>Timeouts, &quot;to be visible&quot;, <code>waitFor</code>, element-not-found-within</td></tr><tr><td><code>network</code></td><td><code>net::</code> / <code>ERR_</code> errors, 5xx responses, <code>ECONNREFUSED</code>, <code>waitForResponse</code> — plus the count of failed and 5xx requests captured on the failing attempts, and any request that failed on the failing attempt but not the passing one</td></tr><tr><td><code>assertion</code></td><td><code>expect(...)</code>, &quot;Expected:&quot;, snapshot/screenshot comparison — with no timing/network noise</td></tr><tr><td><code>environment</code></td><td>Fails repeatedly on exactly one browser while others pass</td></tr><tr><td><code>other</code></td><td>No clear signal</td></tr></tbody></table><p>The classifier weighs more than keywords: it counts the requests that failed or returned 5xx across the test&#39;s recent failing attempts, and — the sharpest signal — weighs each recent flake whose failing attempt made a request that failed while the passing attempt did not (see the <a href="./evidence.html#attempts">attempt diff</a>). Such a request recovering on retry is strong evidence the flakiness is a network problem, so it counts for several keyword matches.</p><p>Filter the flaky table by category to triage a class of failures at once.</p><h3 id="impact-ranking" tabindex="-1">Impact ranking <a class="header-anchor" href="#impact-ranking" aria-label="Permalink to &quot;Impact ranking&quot;">​</a></h3><p>Not all flaky tests are equally expensive. Piwi ranks them by <strong>impact</strong> — derived from wasted CI minutes (retries × average failed duration) and pipeline-block effect — so you fix the ones that hurt most first. A color-coded dot makes it scannable:</p><ul><li>🟢 green — under 5 wasted minutes</li><li>🟡 amber — under 30 minutes</li><li>🔴 red — 30 minutes or more</li></ul><h3 id="per-test-stability-trend" tabindex="-1">Per-test stability trend <a class="header-anchor" href="#per-test-stability-trend" aria-label="Permalink to &quot;Per-test stability trend&quot;">​</a></h3><p>Each test case has a <strong>stability trend</strong>: a time series of pass rate, flaky rate, and average duration, bucketed over time — so you can see whether a fix actually stuck.</p><h2 id="quarantine-with-a-way-out" tabindex="-1">Quarantine, with a way out <a class="header-anchor" href="#quarantine-with-a-way-out" aria-label="Permalink to &quot;Quarantine, with a way out&quot;">​</a></h2><p>Detecting a flaky test doesn&#39;t stop it blocking merges. Quarantine does — without hiding it.</p><p>The usual approach is <code>--grep-invert @quarantine</code>: the test stops running, so nothing ever proves it&#39;s fixed, and the list only grows. A year later nobody remembers why half of it is there.</p><p><strong>A quarantined test in Piwi keeps running and keeps reporting.</strong> It is excluded from the <a href="/guide/ci.html#blocking-a-merge">CI gate</a>&#39;s verdict and nothing else. That single difference is what makes the exit possible:</p><ul><li>Passing runs after quarantine accumulate as a <strong>streak</strong>, and one failure resets it.</li><li>After five consecutive passes the test is flagged <strong>ready to release</strong> — the dashboard tells you, rather than waiting to be asked.</li><li><strong>Candidates</strong> are proposed from the flaky analysis, ranked by <em>wasted CI minutes</em> rather than flakiness score. A test that flakes constantly but finishes in 200 ms costs nothing; one that flakes weekly and burns a four-minute timeout is what actually hurts.</li><li><strong>Debt</strong> is reported in aggregate: how many are quarantined, how many are ready to release, how long the oldest has been in, and how many still have no passing streak at all.</li></ul><p>The gate always states how many failures quarantine excluded — a green gate that silently ignored failures would be worthless — and <code>--max-quarantined</code> sets a ceiling so the list can&#39;t grow unbounded.</p><p>Manage it from the <strong>Quarantine</strong> view of the project&#39;s <strong>Failures</strong> tab, or over the API (<code>GET</code>/<code>POST /api/projects/:id/quarantine</code>, <code>DELETE /api/projects/:id/quarantine/:testCaseId</code>).</p><h2 id="regression-signals" tabindex="-1">Regression signals <a class="header-anchor" href="#regression-signals" aria-label="Permalink to &quot;Regression signals&quot;">​</a></h2><p>Individual test cases in a run carry at-a-glance badges:</p><ul><li><strong><code>NEW</code></strong> (red) — a new regression</li><li><strong><code>FLAKY</code></strong> (purple) — newly flaky</li></ul><p>Toggle filters on the run&#39;s test-case list to show only new regressions or new flaky tests.</p><p>Opening a failing execution surfaces the same signals (see <a href="./evidence.html#one-execution-diagnosis-first">Test case detail</a>): the new-regression / passed-on-retry / newly-flaky badges in the header, the <em>why</em> and <em>since when</em> facts on the headline, and the failing-streak sentence with a link back to the last green run in the history block.</p><h2 id="spec-health-by-file" tabindex="-1">Spec health by file <a class="header-anchor" href="#spec-health-by-file" aria-label="Permalink to &quot;Spec health by file&quot;">​</a></h2><p>The project&#39;s <strong>Tests</strong> tab has a <strong>Group by File</strong> view that groups the tests under each spec file and carries that file&#39;s pass rate, flaky rate, failure count, test count and average time in the group header, so an unhealthy area of the suite jumps out.</p><h2 id="across-every-project" tabindex="-1">Across every project <a class="header-anchor" href="#across-every-project" aria-label="Permalink to &quot;Across every project&quot;">​</a></h2><p>Everything above is scoped to one project. The <strong>Analytics</strong> page lifts the same signals to your whole portfolio over a time window you choose — portfolio health, a pass-rate heatmap, wasted CI minutes, regression velocity, a global flaky leaderboard, and an auto-generated insights feed. See <a href="./analytics.html">Analytics</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./run-changes.html">What changed in a run</a> — the Changes tab: new failures, fixed tests, commits since a baseline</li><li><a href="./slow-tests.html">Slow tests &amp; wasted time</a> — duration trends, slowest tests, and timeout opportunities</li><li><a href="./analytics.html">Analytics</a> — the same signals across every project</li><li><a href="./ui-overview.html">UI overview</a> — where each of these views lives in the dashboard</li><li><a href="/guide/reporter.html">Reporter</a> — how retries, traces, and run metadata get captured</li><li><a href="/guide/capture-fixtures.html">Capture fixtures</a> — the test-side setup behind network analysis and Web Vitals</li><li><a href="./ai-diagnosis.html">AI diagnosis &amp; failure clustering</a> — explain the failures behind the trends</li></ul>',36))])}const v=r(c,[["render",u]]);export{k as __pageData,v as default};
